75	      font-size: 13px;
76	    }
77	
78	    main {
79	      display: grid;
80	      grid-template-columns: minmax(0, 1.05fr) minmax(400px, .95fr);
81	      gap: 68px;
82	      align-items: center;
83	    }
84	
85	    .eyebrow {
86	      margin: 0 0 16px;
87	      color: var(--brand);
88	      font-size: 13px;
89	      font-weight: 800;
90	      letter-spacing: .12em;
91	      text-transform: uppercase;
92	    }
93	
94	    h1 {
95	      max-width: 640px;
96	      margin: 0;
97	      font-family: Georgia, "Times New Roman", serif;
98	      font-size: clamp(48px, 6vw, 78px);
99	      font-weight: 500;
100	      letter-spacing: -.045em;
101	      line-height: .98;
