171	    input:focus, textarea:focus {
172	      border-color: var(--brand);
173	      box-shadow: 0 0 0 4px rgba(23,107,85,.1);
174	    }
175	
176	    .url-row {
177	      display: flex;
178	      gap: 10px;
179	    }
180	
181	    .url-row input { min-width: 0; }
182	
183	    button {
184	      border: 0;
185	      border-radius: 11px;
186	      padding: 13px 18px;
187	      cursor: pointer;
188	      font-weight: 760;
