276	<body>
277	  <div class="shell" data-harness-ready="true">
278	    <header>
279	      <div class="brand"><span class="brand-mark">⌑</span> Pocketmark</div>
280	      <div class="personal">Your personal library</div>
281	    </header>
282	
283	    <main>
284	      <section>
285	        <p class="eyebrow">A home for useful things</p>
286	        <h1>Save it now.<br>Find it when it matters.</h1>
287	        <p class="intro">Your collection is empty. Start with one useful link and Pocketmark will fill in the details for you.</p>
288	      </section>
289	
290	      <section class="card" id="capture-card">
291	        <div class="step"><span class="dot"></span><span id="step-label">Add your first bookmark</span></div>
292	
293	        <form id="url-form">
294	          <h2>What do you want to keep?</h2>
295	          <p class="helper">Paste a web address. We’ll look up the page and prepare it for your library.</p>
296	          <label for="url">Web address</label>
297	          <div class="url-row">
298	            <input id="url" name="url" type="url" required autocomplete="url" placeholder="https://example.com/article">
299	            <button class="primary" type="submit">Get details</button>
300	          </div>
301	          <p class="error" id="url-error">Enter a full web address beginning with http:// or https://</p>
302	        </form>
303	
304	        <div class="details" id="details" aria-live="polite">
305	          <h2>Here’s what we found</h2>
306	          <p class="helper">These details will help you recognise and find this page later. You can change either one.</p>
307	          <div class="source"><span class="source-icon">↗</span><span id="source-host"></span></div>
308	          <div class="field">
309	            <label for="title">Title</label>
310	            <input id="title" value="The quiet power of a daily walk">
311	          </div>
312	          <div class="field">
313	            <label for="description">Page description</label>
314	            <textarea id="description">A practical look at how a short daily walk can improve focus, mood, and long-term wellbeing.</textarea>
315	          </div>
316	          <div class="actions">
317	            <span class="fetched">✓ Filled in from the page</span>
318	            <button class="save-placeholder" type="button" disabled>Save bookmark</button>
319	          </div>
320	        </div>
321	      </section>
322	    </main>
323	  </div>
324	
325	  <script>
326	    const form = document.querySelector('#url-form');
327	    const input = document.querySelector('#url');
328	    const error = document.querySelector('#url-error');
329	    const details = document.querySelector('#details');
330	    const sourceHost = document.querySelector('#source-host');
331	    const stepLabel = document.querySelector('#step-label');
332	
333	    form.addEventListener('submit', (event) => {
334	      event.preventDefault();
335	      let parsed;
336	      try {
337	        parsed = new URL(input.value.trim());
338	        if (!['http:', 'https:'].includes(parsed.protocol)) throw new Error('unsupported');
339	      } catch (_) {
340	        error.style.display = 'block';
341	        details.classList.remove('visible');
342	        return;
343	      }
344	
345	      error.style.display = 'none';
346	      sourceHost.textContent = parsed.hostname.replace(/^www\./, '');
347	      form.style.display = 'none';
348	      details.classList.add('visible');
349	      stepLabel.textContent = 'Review the page details';
350	      document.querySelector('#title').focus();
351	    });
352	  </script>
353	</body>
354	</html>
